import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import styles from './CommunitiesDiscovery.module.css';
import CommunityCard from './CommunityCard';

const CommunitiesDiscovery = () => {
    const navigate = useNavigate();
    const [communities, setCommunities] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchDiscovery = async () => {
            try {
                setLoading(true);
                // Делаем запрос к list endpoint (на бэке там order_by('?'))
                const resp = await axios.get('http://127.0.0.1:8000/api/communities/', {
                    headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
                });
                
                setCommunities(resp.data.results || resp.data || []);
            } catch (err) {
                console.error(err);
                setError("Не удалось загрузить рекомендации");
            } finally {
                setLoading(false);
            }
        };

        fetchDiscovery();
    }, []);

    return (
        <div className={styles.outContainer}>
            <div className={styles.container}>
                {/* Header */}
                <header className={styles.header}>
                    <img 
                        src="/images/logo.svg" 
                        alt="Logo" 
                        className={styles.logo} 
                        onClick={() => navigate('/')}
                    />
                    <h2 className={styles.pageTitle}>Интересные сообщества</h2>
                    <img 
                        src="/images/back.svg" 
                        alt="Back" 
                        className={styles.backIcon} 
                        onClick={() => navigate(-1)} 
                    />
                </header>

                {/* Content */}
                <div className={styles.list}>
                    {loading && <p className={styles.status}>Ищем самое интересное... 🚀</p>}
                    {error && <p className={styles.error}>{error}</p>}
                    
                    {!loading && !error && communities.length === 0 && (
                        <p className={styles.status}>Пока нет сообществ :(</p>
                    )}

                    {communities.map((comm) => (
                        <CommunityCard key={comm.id} community={comm} />
                    ))}
                </div>
            </div>
        </div>
    );
};

export default CommunitiesDiscovery;
